// Drizzle schema for the Neon (Postgres) database.
//
// Design notes:
// - Primary keys are UUIDs generated by Postgres (gen_random_uuid()).
// - Money columns are numeric(12,2) read back as JS numbers.
// - Snapshot-style nested data (order items, addresses, customer info,
//   fragrance notes, settings sections) lives in jsonb columns. That keeps
//   the API response shapes identical to the old Mongo documents, so the
//   admin and storefront UIs did not need to change.
//
// Only relative imports here: the seed scripts import this file directly.
import { sql } from "drizzle-orm";
import {
  pgTable,
  uuid,
  text,
  integer,
  boolean,
  numeric,
  doublePrecision,
  timestamp,
  jsonb,
  index,
  uniqueIndex,
} from "drizzle-orm/pg-core";

const money = (name) => numeric(name, { precision: 12, scale: 2, mode: "number" });

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

const textArray = (name) =>
  text(name)
    .array()
    .notNull()
    .default(sql`'{}'::text[]`);

// Admin users ---------------------------------------------------------------

export const adminUsers = pgTable("admin_users", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  name: text("name").notNull().default(""),
  role: text("role", { enum: ["admin", "superadmin"] }).notNull().default("admin"),
  lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
  ...timestamps,
});

// Categories ----------------------------------------------------------------

export const categories = pgTable("categories", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  description: text("description").notNull().default(""),
  image: text("image").notNull().default(""),
  order: integer("order").notNull().default(0),
  isActive: boolean("is_active").notNull().default(true),
  ...timestamps,
});

// Products ------------------------------------------------------------------

export const products = pgTable(
  "products",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    slug: text("slug").notNull().unique(),
    description: text("description").notNull().default(""),
    shortDescription: text("short_description").notNull().default(""),

    price: money("price").notNull(),
    originalPrice: money("original_price"),

    // Category slug (matches categories.slug). Stored as a plain string so
    // storefront filters don't need a join.
    category: text("category").notNull().default(""),

    fragranceFamily: text("fragrance_family").notNull().default(""),
    size: text("size").notNull().default(""),
    brand: text("brand").notNull().default(""),
    sku: text("sku").notNull().default(""),

    // Cloudinary secure URLs.
    images: textArray("images"),

    stock: integer("stock").notNull().default(0),
    isHotDeal: boolean("is_hot_deal").notNull().default(false),
    isNewArrival: boolean("is_new_arrival").notNull().default(false),

    rating: doublePrecision("rating").notNull().default(0),
    reviewCount: integer("review_count").notNull().default(0),
    discount: doublePrecision("discount").notNull().default(0),

    notes: jsonb("notes")
      .notNull()
      .default({ top: [], middle: [], base: [] }),

    badge: text("badge").notNull().default(""),
    status: text("status", { enum: ["active", "draft", "archived"] })
      .notNull()
      .default("draft"),
    ...timestamps,
  },
  (t) => [
    index("products_category_idx").on(t.category),
    index("products_status_idx").on(t.status),
    index("products_created_at_idx").on(t.createdAt),
  ]
);

// Orders --------------------------------------------------------------------

export const orders = pgTable(
  "orders",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orderNumber: text("order_number").notNull().unique(),

    // [{ productId, name, price, quantity, image, sku }] - a snapshot of the
    // cart at checkout time.
    items: jsonb("items").notNull().default([]),

    subtotal: money("subtotal").notNull().default(0),
    shipping: money("shipping").notNull().default(0),
    tax: money("tax").notNull().default(0),
    total: money("total").notNull().default(0),
    currency: text("currency").notNull().default("USD"),

    paymentMethod: text("payment_method", { enum: ["cod", "stripe"] }).notNull(),
    paymentStatus: text("payment_status", {
      enum: ["pending", "paid", "failed", "refunded", "cod_pending", "cod_collected"],
    })
      .notNull()
      .default("pending"),
    stripeSessionId: text("stripe_session_id").notNull().default(""),
    stripePaymentIntentId: text("stripe_payment_intent_id").notNull().default(""),

    status: text("status", {
      enum: ["pending", "processing", "shipped", "delivered", "cancelled"],
    })
      .notNull()
      .default("pending"),

    // Customer email is a real column (indexed, used to group customers);
    // the rest of the profile snapshot is jsonb.
    customerEmail: text("customer_email").notNull(),
    customer: jsonb("customer").notNull().default({}),

    shippingAddress: jsonb("shipping_address").notNull().default({}),
    billingAddress: jsonb("billing_address").notNull().default({}),

    customerNotes: text("customer_notes").notNull().default(""),
    adminNotes: text("admin_notes").notNull().default(""),

    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    cancelReason: text("cancel_reason").notNull().default(""),
    ...timestamps,
  },
  (t) => [
    index("orders_created_at_idx").on(t.createdAt),
    index("orders_customer_email_idx").on(t.customerEmail, t.createdAt),
    index("orders_status_idx").on(t.status),
    index("orders_payment_status_idx").on(t.paymentStatus),
    index("orders_stripe_session_idx").on(t.stripeSessionId),
    index("orders_stripe_pi_idx").on(t.stripePaymentIntentId),
  ]
);

// Coupons -------------------------------------------------------------------

export const coupons = pgTable(
  "coupons",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    code: text("code").notNull(),
    description: text("description").notNull().default(""),
    type: text("type", { enum: ["percent", "fixed", "free_shipping"] })
      .notNull()
      .default("percent"),
    // percent: 0-100, fixed: amount, free_shipping: ignored.
    value: doublePrecision("value").notNull().default(0),
    minPurchase: money("min_purchase").notNull().default(0),
    maxDiscount: money("max_discount"),
    validFrom: timestamp("valid_from", { withTimezone: true }),
    validUntil: timestamp("valid_until", { withTimezone: true }),
    usageLimit: integer("usage_limit"),
    perCustomerLimit: integer("per_customer_limit"),
    usedCount: integer("used_count").notNull().default(0),
    applicableCategories: textArray("applicable_categories"),
    applicableProducts: textArray("applicable_products"),
    isActive: boolean("is_active").notNull().default(true),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("coupons_code_idx").on(t.code),
    index("coupons_active_idx").on(t.isActive, t.validUntil),
  ]
);

// Offers --------------------------------------------------------------------

export const offers = pgTable(
  "offers",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    title: text("title").notNull(),
    subtitle: text("subtitle").notNull().default(""),
    description: text("description").notNull().default(""),
    type: text("type", {
      enum: ["banner", "hero", "flash_sale", "bogo", "featured", "announcement"],
    })
      .notNull()
      .default("banner"),
    image: text("image").notNull().default(""),
    link: text("link").notNull().default(""),
    ctaText: text("cta_text").notNull().default(""),
    discountPercent: doublePrecision("discount_percent").notNull().default(0),
    startsAt: timestamp("starts_at", { withTimezone: true }),
    endsAt: timestamp("ends_at", { withTimezone: true }),
    applicableProducts: textArray("applicable_products"),
    applicableCategories: textArray("applicable_categories"),
    order: integer("order").notNull().default(0),
    isActive: boolean("is_active").notNull().default(true),
    ...timestamps,
  },
  (t) => [index("offers_active_order_idx").on(t.isActive, t.order)]
);

// Testimonials --------------------------------------------------------------

export const testimonials = pgTable(
  "testimonials",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    location: text("location").notNull().default(""),
    rating: integer("rating").notNull().default(5),
    body: text("body").notNull(),
    image: text("image").notNull().default(""),
    order: integer("order").notNull().default(0),
    isActive: boolean("is_active").notNull().default(true),
    ...timestamps,
  },
  (t) => [index("testimonials_active_order_idx").on(t.isActive, t.order)]
);

// Site settings (single row, id = "site") ------------------------------------

export const SETTINGS_DEFAULTS = {
  announcementBar: { text: "", link: "", isActive: false },
  storeInfo: { name: "Mushk Perfumes", tagline: "", email: "", phone: "", address: "" },
  social: { facebook: "", instagram: "", twitter: "", youtube: "", tiktok: "" },
  seo: { defaultTitle: "", defaultDescription: "", ogImage: "" },
  shipping: { freeShippingThreshold: 100, flatRate: 10, taxRate: 0.08 },
};

export const settings = pgTable("settings", {
  id: text("id").primaryKey().default("site"),
  announcementBar: jsonb("announcement_bar").notNull().default(SETTINGS_DEFAULTS.announcementBar),
  storeInfo: jsonb("store_info").notNull().default(SETTINGS_DEFAULTS.storeInfo),
  social: jsonb("social").notNull().default(SETTINGS_DEFAULTS.social),
  seo: jsonb("seo").notNull().default(SETTINGS_DEFAULTS.seo),
  shipping: jsonb("shipping").notNull().default(SETTINGS_DEFAULTS.shipping),
  ...timestamps,
});
